      ]
    },
    {
      "candidate_id": "candidate:0004",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0004",
          "source_quote": "4. 管理销售漏斗。"
        }
      ]
