    {
      "candidate_id": "candidate:0005",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0005",
          "source_quote": "5. 设计渠道合作政策。"
