      ]
    },
    {
      "candidate_id": "candidate:0006",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0006",
          "source_quote": "6. 建设客户分层规则。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0007",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0007",
          "source_quote": "7. 制定续费运营机制。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0008",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0008",
          "source_quote": "8. 设计增购运营机制。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0009",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0009",
          "source_quote": "9. 管理重点客户风险。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0010",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0010",
          "source_quote": "10. 建立合同评审流程。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0011",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0011",
          "source_quote": "11. 建立回款跟踪流程。"
