    {
      "candidate_id": "candidate:0012",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0012",
          "source_quote": "12. 设计折扣审批机制。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0013",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0013",
          "source_quote": "13. 规划商业化数据看板。"
