    },
    {
      "candidate_id": "candidate:0014",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0014",
          "source_quote": "14. 分析获客成本。"
