    {
      "candidate_id": "candidate:0015",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0015",
          "source_quote": "15. 分析客户终身价值。"
