    {
      "candidate_id": "candidate:0016",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0016",
          "source_quote": "16. 组织月度经营复盘。"
