    {
      "candidate_id": "candidate:0017",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0017",
          "source_quote": "17. 推动销售与产品协作。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0018",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0018",
          "source_quote": "18. 推动销售与交付协作。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0019",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0019",
          "source_quote": "19. 管理渠道冲突。"
