      ]
    },
    {
      "candidate_id": "candidate:0020",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0020",
          "source_quote": "20. 设计试用转化流程。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0021",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0021",
          "source_quote": "21. 设计流失预警规则。"
        }
