    {
      "candidate_id": "candidate:0022",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0022",
          "source_quote": "22. 建立客户反馈闭环。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0023",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0023",
          "source_quote": "23. 维护商业化知识库。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0024",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0024",
          "source_quote": "24. 建设销售赋能材料。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0025",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0025",
          "source_quote": "25. 设计合作伙伴培训。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0026",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0026",
          "source_quote": "26. 建立价格实验流程。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0027",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0027",
          "source_quote": "27. 管理商业化项目预算。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0028",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0028",
          "source_quote": "28. 识别收入确认风险。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0029",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0029",
          "source_quote": "29. 建立经营指标口径。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0030",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0030",
          "source_quote": "30. 规划新市场验证。"
        }
      ]
    },
    {
      "candidate_id": "candidate:0031",
      "category": "responsibility",
      "sources": [
        {
          "source_field": "job_responsibilities",
          "source_unit_id": "job_responsibilities:0031",
